const handlers = new Map([
  ["circle:square", (c, s) => `circle ${c.radius} vs square ${s.side}`],
  ["square:circle", (s, c) => handlers.get("circle:square")(c, s)],   // canonicalise
  ["circle:circle", () => "two circles"],
]);

function collide(a, b) {
  const hit = handlers.get(`${a.kind}:${b.kind}`);
  if (!hit) throw new TypeError(`unhandled pair ${a.kind}/${b.kind}`);
  return hit(a, b);
}

