class Circle {
  collideWith(other) { return other.collideWithCircle(this); }   // dispatch #1 -> #2
}

class Square {
  collideWith(other) { return other.collideWithSquare(this); }
  collideWithCircle(circle) { return `circle ${circle.radius} vs square ${this.side}`; }
}
